" y=\"134\" font-size=\"15\" font-weight=\"bold\" text-anchor=\"middle\" fill=\"#1e293b\">Al</text><rect x=\"222\" y=\"106\" width=\"52\" height=\"38\" fill=\"#fef3c7\" stroke=\"#475569\" stroke-width=\"1.2\"/><text x=\"225\" y=\"117\" font-size=\"10\" fill=\"#475569\">14</text><text x=\"248\" y=\"134\" font-size=\"15\" font-weight=\"bold\" text-anchor=\"middle\" fill=\"#1e293b\">Si</text><rect x=\"276\" y=\"106\" width=\"52\" height=\"38\" fill=\"#dcfce7\" stroke=\"#7c3aed\" stroke-width=\"3\"/><text x=\"279\" y=\"117\" font-size=\"10\" fill=\"#475569\">15</text><text x=\"302\" y=\"134\" font-size=\"15\" font-weight=\"bold\" text-anchor=\"middle\" fill=\"#1e293b\">P</text><circle cx=\"320\" cy=\"115\" r=\"9\" fill=\"#7c3aed\"/><text x=\"320\" y=\"119\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\" fill=\"#fff\">Z</text><rect x=\"330\" y=\"106\" width=\"52\" height=\"38\" fill=\"#dcfce7\" stroke=\"#475569\" stroke-width=\"1.2\"/><text x=\"333\" y=\"117\" font-size=\"10\" fill=\"#475569\">16</text><text x=\"356\" y=\"134\" font-size=\"15\" font-weight=\"bold\" text-anchor=\"middle\" fill=\"#1e293b\">S</text><rect x=\"384\" y=\"106\" width=\"52\" height=\"38\" fill=\"#dcfce7\" stroke=\"#475569\" stroke-width=\"1.2\"/><text x=\"387\" y=\"117\" font-size=\"10\" fill=\"#475569\">17</text><text x=\"410\" y=\"134\" font-size=\"15\" font-weight=\"bold\" text-anchor=\"middle\" fill=\"#1e293b\">Cl</text><rect x=\"438\" y=\"106\" width=\"52\" height=\"38\" fill=\"#ede9fe\" stroke=\"#475569\" stroke-width=\"1.2\"/><text x=\"441\" y=\"117\" font-size=\"10\" fill=\"#475569\">18</text><text x=\"464\" y=\"134\" font-size=\"15\" font-weight=\"bold\" text-anchor=\"middle\" fill=\"#1e293b\">Ar</text><rect x=\"40\" y=\"155\" width=\"16\" height=\"14\" fill=\"#dbeafe\" stroke=\"#475569\"/><text x=\"61\" y=\"166\" font-size=\"13\" fill=\"#1e293b\">metal</text><rect x=\"150\" y=\"155\" width=\"16\" height=\"14\" fill=\"#fef3c7\" stroke=\"#475569\"/><text x=\"171\" y=\"166\" font-size=\"13\" fill=\"#1e293b\">yarı metal</text><rect x=\"260\" y=\"155\" width=\"16\" height=\"14\" fill=\"#dcfce7\" stroke=\"#475569\"/><text x=\"281\" y=\"166\" font-size=\"13\" fill=\"#1e293b\">ametal</text><rect x=\"370\" y=\"155\" width=\"16\" height=\"14\" fill=\"#ede9fe\" stroke=\"#475569\"/><text x=\"391\" y=\"166\" font-size=\"13\" fill=\"#1e293b\">soy gaz</text></svg><figcaption>Kartlara göre X, Y ve Z’nin yeri</figcaption></figure><table class=\"sv-c\"><tr><td>I</td><td>15 &gt; 7 → doğru.</td></tr><tr><td>II</td><td>C, N, P ametal → doğru.</td></tr><tr><td>III</td><td>X 2. periyotta, Z 3. periyotta → yanlış.</td></tr><tr class=\"ok\"><td>B</td><td>I ve II</td></tr></table><div class=\"sv-w\"><b>Tuzak:</b> Fosforu metal sanıp II’yi yanlış saymak.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>"
