" r=\"9\" fill=\"#dc2626\"/><text x=\"142\" y=\"119\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\" fill=\"#fff\">4</text><rect x=\"168\" y=\"106\" width=\"52\" height=\"38\" fill=\"#dbeafe\" stroke=\"#475569\" stroke-width=\"1.2\"/><text x=\"171\" y=\"117\" font-size=\"10\" fill=\"#475569\">13</text><text x=\"194\" y=\"134\" font-size=\"15\" font-weight=\"bold\" text-anchor=\"middle\" fill=\"#1e293b\">Al</text><rect x=\"222\" y=\"106\" width=\"52\" height=\"38\" fill=\"#fef3c7\" stroke=\"#475569\" stroke-width=\"1.2\"/><text x=\"225\" y=\"117\" font-size=\"10\" fill=\"#475569\">14</text><text x=\"248\" y=\"134\" font-size=\"15\" font-weight=\"bold\" text-anchor=\"middle\" fill=\"#1e293b\">Si</text><rect x=\"276\" y=\"106\" width=\"52\" height=\"38\" fill=\"#dcfce7\" stroke=\"#475569\" stroke-width=\"1.2\"/><text x=\"279\" y=\"117\" font-size=\"10\" fill=\"#475569\">15</text><text x=\"302\" y=\"134\" font-size=\"15\" font-weight=\"bold\" text-anchor=\"middle\" fill=\"#1e293b\">P</text><rect x=\"330\" y=\"106\" width=\"52\" height=\"38\" fill=\"#dcfce7\" stroke=\"#475569\" stroke-width=\"1.2\"/><text x=\"333\" y=\"117\" font-size=\"10\" fill=\"#475569\">16</text><text x=\"356\" y=\"134\" font-size=\"15\" font-weight=\"bold\" text-anchor=\"middle\" fill=\"#1e293b\">S</text><rect x=\"384\" y=\"106\" width=\"52\" height=\"38\" fill=\"#dcfce7\" stroke=\"#dc2626\" stroke-width=\"3\"/><text x=\"387\" y=\"117\" font-size=\"10\" fill=\"#475569\">17</text><text x=\"410\" y=\"134\" font-size=\"15\" font-weight=\"bold\" text-anchor=\"middle\" fill=\"#1e293b\">Cl</text><circle cx=\"428\" cy=\"115\" r=\"9\" fill=\"#dc2626\"/><text x=\"428\" y=\"119\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\" fill=\"#fff\">5</text><rect x=\"438\" y=\"106\" width=\"52\" height=\"38\" fill=\"#ede9fe\" stroke=\"#475569\" stroke-width=\"1.2\"/><text x=\"441\" y=\"117\" font-size=\"10\" fill=\"#475569\">18</text><text x=\"464\" y=\"134\" font-size=\"15\" font-weight=\"bold\" text-anchor=\"middle\" fill=\"#1e293b\">Ar</text><rect x=\"44\" y=\"146\" width=\"52\" height=\"38\" fill=\"#dbeafe\" stroke=\"#16a34a\" stroke-width=\"3\"/><text x=\"47\" y=\"157\" font-size=\"10\" fill=\"#475569\">19</text><text x=\"70\" y=\"174\" font-size=\"15\" font-weight=\"bold\" text-anchor=\"middle\" fill=\"#1e293b\">K</text><circle cx=\"88\" cy=\"155\" r=\"9\" fill=\"#16a34a\"/><text x=\"88\" y=\"159\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\" fill=\"#fff\">3</text><rect x=\"98\" y=\"146\" width=\"52\" height=\"38\" fill=\"#dbeafe\" stroke=\"#475569\" stroke-width=\"1.2\"/><text x=\"101\" y=\"157\" font-size=\"10\" fill=\"#475569\">20</text><text x=\"124\" y=\"174\" font-size=\"15\" font-weight=\"bold\" text-anchor=\"middle\" fill=\"#1e293b\">Ca</text><rect x=\"40\" y=\"195\" width=\"16\" height=\"14\" fill=\"#dbeafe\" stroke=\"#475569\"/><text x=\"61\" y=\"206\" font-size=\"13\" fill=\"#1e293b\">metal</text><rect x=\"150\" y=\"195\" width=\"16\" height=\"14\" fill=\"#fef3c7\" stroke=\"#475569\"/><text x=\"171\" y=\"206\" font-size=\"13\" fill=\"#1e293b\">yarı metal</text><rect x=\"260\" y=\"195\" width=\"16\" height=\"14\" fill=\"#dcfce7\" stroke=\"#475569\"/><text x=\"281\" y=\"206\" font-size=\"13\" fill=\"#1e293b\">ametal</text><rect x=\"370\" y=\"195\" width=\"16\" height=\"14\" fill=\"#ede9fe\" stroke=\"#475569\"/><text x=\"391\" y=\"206\" font-size=\"13\" fill=\"#1e293b\">soy gaz</text></svg><figcaption>Yeşil işaretli 2 (Li) ve 3 (K), sodyumla aynı gruptaki alkali metallerdir</figcaption></figure><table class=\"sv-c\"><tr><td>A</td><td>1 hidrojendir; ametal ve gaz, “yumuşak metal” olamaz.</td></tr><tr class=\"ok\"><td>B</td><td>2 (Li) ve 3 (K) alkali metal → doğru.</td></tr><tr><td>C</td><td>4 (Mg) komşudur ama farklı grupta; özellikleri “çok benzer” değil.</td></tr><tr><td>D</td><td>4 (Mg) farklı grupta.</td></tr></table><div class=\"sv-w\"><b>Tuzak:</b> Komşu elementin (Mg) özelliklerinin benzer olduğunu sanmak. Benzerlik sütunda (grupta) aranır.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>"
